from threetears.evals import Eval

from slots import free_slots, from_request

def find(case):
    """The free slots the finder offers for the request."""
    return {"slots": [slot.strftime("%H:%M") for slot in free_slots(*from_request(case))]}


def offers_the_slots(case, out):
    """The finder offers exactly the slots that were offered."""
    return out["slots"] == case["offered"]

requests = Eval("data/requests.jsonl", runner=find, grader=[offers_the_slots], k=1)
